struct matrix4x4 { float m[16]; };

class PanelQuad
{
public:
  bool animating;
  void StartAnim(bool value) { animating = value; }
};

class PanelAnim
{
public:
  char data[108];
  PanelAnim *next;
  PanelQuad *quad;
};

class PanelAnimFile
{
public:
  PanelAnim* obs;
  float totalseconds;
};

enum AnimType
{
  PLAY,
  PLAY_BACKWARD,
  PING_PONG,
};

enum
{
  NO_FLAGS = 0x00,
  ALREADY_PLAYING = 0x01,
  HOLD_AFTER_PLAYING = 0x02,
  LOOP = 0x04,
  PING_PONGING = 0x08,
};

class PanelAnimEvent
{
public:
  float current_time;
  float start_offset;
  float total_time;
  PanelAnimEvent *next;
  PanelAnimEvent *prev;
  int flags;
  matrix4x4 offsets;
  AnimType type;
  PanelAnimFile *animation;

  PanelAnimEvent() { next = 0; prev = 0; animation = 0; }
};

class PanelAnimManager
{
private:
  PanelAnimEvent eventlist;
public:
  PanelAnimEvent *Play(PanelAnimFile* anim, AnimType play_type, int flags);
  PanelAnimEvent *Find(PanelAnimFile &anim);
};

extern matrix4x4 identity_matrix;
void *operator new(unsigned int, unsigned int, const char *, int);
#define NEW new(0, __FILE__, 0)
#ifndef NULL
#define NULL 0
#endif

PanelAnimEvent *PanelAnimManager::Play(PanelAnimFile* anim, AnimType play_type, int flags)
{
	PanelAnimEvent *new_event = NULL;

	if(flags & ALREADY_PLAYING)
	{
		new_event = Find(*anim);
		flags &= ~ALREADY_PLAYING;
	}

	//  If the event was not already listed, then make room for it.
	if(new_event == NULL)
	{
		new_event = NEW PanelAnimEvent;
		new_event->next = eventlist.next;
		new_event->prev = &eventlist;
		eventlist.next = new_event;
		if(new_event->next)
			new_event->next->prev = new_event;
	}

	new_event->animation = anim;
	PanelAnim* object = new_event->animation->obs;
	while(object)
	{
		object->quad->StartAnim(true);
		object = object->next;
	}
	new_event->current_time = 0;  //  Start and endtime will be set the first time an anim is drawn.
	new_event->start_offset = 0;  //  There are no offsets when we play the whole animation.
	new_event->total_time = new_event->animation->totalseconds;
	new_event->offsets = identity_matrix;

	new_event->flags = flags;

	if(play_type == PING_PONG)
	{
		new_event->type = PLAY;            //  Just start out playing forward.
		new_event->flags |= PING_PONGING;
	}
	else
	{
		new_event->type = play_type;
		new_event->flags &= ~PING_PONGING;
	}

	return new_event;

}
